const criteria = $('Normalize Search Criteria').first().json;
const rows = $input.all().map((item) => item.json);

function norm(value) {
  return String(value ?? '').trim().toLowerCase();
}

function normalizeListingType(value) {
  const text = norm(value);
  if (text === 'buy' || text === 'purchase') return 'sale';
  if (text === 'lease' || text === 'renting') return 'rent';
  return text;
}

function toValueList(value) {
  return norm(value)
    .split(/,| or | \/ |\//)
    .map((part) => part.trim())
    .filter((part) => part.length > 0);
}

const wantedLocations = toValueList(criteria.location);
const wantedTypes = toValueList(criteria.property_type);
const wantedListingTypes = toValueList(criteria.listing_type).map(normalizeListingType);
const wantedBedrooms = Number.parseInt(criteria.bedrooms, 10);
const maxPrice = Number.parseFloat(criteria.max_price);

const matches = rows.filter((row) => {
  const status = norm(row.status);
  if (status === 'sold' || status === 'rented' || status === 'pending_review') {
    return false;
  }
  const rowLocation = norm(row.location);
  if (wantedLocations.length > 0 && !wantedLocations.some((loc) => rowLocation.includes(loc))) {
    return false;
  }
  if (wantedTypes.length > 0 && !wantedTypes.includes(norm(row.property_type))) {
    return false;
  }
  if (wantedListingTypes.length > 0 && !wantedListingTypes.includes(normalizeListingType(row.listing_type))) {
    return false;
  }
  const rowBedrooms = Number.parseInt(row.bedrooms, 10);
  if (Number.isInteger(wantedBedrooms) && Number.isInteger(rowBedrooms) && rowBedrooms < wantedBedrooms) {
    return false;
  }
  const rowPrice = Number.parseFloat(row.price);
  if (Number.isFinite(maxPrice) && Number.isFinite(rowPrice) && rowPrice > maxPrice) {
    return false;
  }
  return true;
});

const summaryLines = matches.slice(0, 5).map((row) => {
  const bedroomsPart = Number.isInteger(Number.parseInt(row.bedrooms, 10))
    ? row.bedrooms + '-bed '
    : '';
  return row.property_id + ': ' + bedroomsPart + row.property_type + ' in ' + row.location + ' for ' + row.price;
});

const message = matches.length > 0
  ? 'I found ' + matches.length + ' matching properties. ' + summaryLines.join('. ')
  : 'I could not find any properties matching that right now. Would you like me to adjust the budget or location?';

return [
  {
    json: {
      match_count: matches.length,
      matches: matches,
      message: message
    }
  }
];

const request = $('Normalize Visit Request').first().json;

function normalizeDate(value) {
  const text = String(value ?? '').trim();
  let match = text.match(/^(\d{4})-(\d{1,2})-(\d{1,2})$/);
  if (match) {
    return match[1] + '-' + match[2].padStart(2, '0') + '-' + match[3].padStart(2, '0');
  }
  match = text.match(/^(\d{1,2})\/(\d{1,2})\/(\d{4})$/);
  if (match) {
    return match[3] + '-' + match[1].padStart(2, '0') + '-' + match[2].padStart(2, '0');
  }
  return text;
}

function normalizeTime(value) {
  const text = String(value ?? '').trim().toUpperCase();
  const match = text.match(/^(\d{1,2})(?::(\d{2}))?\s*(AM|PM)?$/);
  if (!match) {
    return text;
  }
  let hour = Number(match[1]);
  const minute = Number(match[2] ?? 0);
  const period = match[3];
  if (period === 'AM' && hour === 12) {
    hour = 0;
  } else if (period === 'PM' && hour !== 12) {
    hour += 12;
  }
  return String(hour).padStart(2, '0') + ':' + String(minute).padStart(2, '0');
}

const requestedDate = normalizeDate(request.visit_date);
const requestedTime = normalizeTime(request.visit_time);
const propertyId = String(request.property_id ?? '').trim();
const SLOTS_PER_TIME = 1;

const rows = $input.all().map((item) => item.json);

const conflicting = rows.filter((row) => {
  const status = String(row.status ?? 'booked').trim().toLowerCase();
  return (
    String(row.property_id ?? '').trim() === propertyId &&
    normalizeDate(row.visit_date) === requestedDate &&
    normalizeTime(row.visit_time) === requestedTime &&
    status !== 'cancelled'
  );
});

const available = conflicting.length < SLOTS_PER_TIME;

return [
  {
    json: {
      available: available,
      property_id: propertyId,
      date: requestedDate,
      time: requestedTime
    }
  }
];

const request = $('Normalize Details Request').first().json;
const rows = $input.all().map((item) => item.json);

function norm(value) {
  return String(value ?? '').trim().toLowerCase();
}

const wantedId = norm(request.property_id);
const wantedLocation = norm(request.location);

const match = rows.find((row) => {
  if (wantedId) {
    return norm(row.property_id) === wantedId;
  }
  if (wantedLocation) {
    return norm(row.location).includes(wantedLocation);
  }
  return false;
});

if (!match) {
  return [
    {
      json: {
        found: false,
        message: 'I could not find a property matching that reference. Could you confirm the property ID or address?'
      }
    }
  ];
}

const message = 'Property ' + match.property_id + ' is a ' + match.bedrooms + '-bed ' + match.property_type +
  ' in ' + match.location + ', ' + match.size + ', listed for ' + match.price + ' (' + match.listing_type + '). ' +
  match.description;

return [
  {
    json: {
      found: true,
      property_id: match.property_id,
      property_type: match.property_type,
      location: match.location,
      size: match.size,
      price: match.price,
      bedrooms: match.bedrooms,
      description: match.description,
      listing_type: match.listing_type,
      status: match.status,
      message: message
    }
  }
];
